//-------------------------------------------------------------------------------------
//-------------------------Debug Signals assignment--------------------

//------------ optional Ports assignments --------------

// (comment fixed: these were dark_period_ctrl/tx_burst_seq requests in the
//  bring-up era; both modules are long gone)
wire qwn_rxcdrhold;          // fabric request from qwn_rx_lane's rxcdrhold_ctrl
                             // (B7 HOLD_FOREVER policy -- see lane instance)
wire qwn_txinhibit;          // fabric request from tx_word_stream (dark phase)
wire qwn1_rxcdrhold;         // lane-1 (dual-lane: cross-SFP TX1<->RX2)
wire qwn1_txinhibit;
// VIO bring-up override controls (declared/driven in the debug block below)
wire        vio_soft_reset;
wire [2:0]  qwn_loopback_sel;
// vio_cdrhold_mode = THE pivotal A/B lever of the 2026-06 campaign (VIO
// probe_out2, no rebuild needed). RXCDRHOLD freezes the GT CDR's phase
// interpolator + frequency integrator, i.e. the recovered-clock grid stops
// following the data. Dose-response measured on C6A (identical conditions):
//   mode 2 force-track (re-acquire every burst): 26% stragglers at -6.4 ns
//          (one full rxusrclk2 cycle), sigma 2910 ps
//   mode 0 fabric per-burst hold:                ~2% at +-3.2 ns, sigma 480 ps
//   mode 1 force-hold (never re-acquire):        ZERO stragglers, sigma 102 ps
// => CDR RE-ACQUISITION TRANSIENTS DISPLACE THE RECOVERED-CLOCK GRID UNDER
// THE ARMED GATE. This is invisible to every in-domain observable BY
// CONSTRUCTION (the whole clock domain moves together; only an external
// reference -- the H31 scope channel -- can see it). Led to B7 HOLD_FOREVER.
wire [1:0]  vio_cdrhold_mode;   // 0=fabric, 1=force hold(1), 2=force track(0)
wire [1:0]  vio_txinh_mode;     // 0=fabric, 1=force inhibit(1), 2=force enable(0)
wire [1:0]  vio_txdis_mode;     // SFP laser: 0=fabric, 1=force OFF, 2=force ON
wire qwn_rxcdrhold_eff = (vio_cdrhold_mode==2'd1) ? 1'b1 :
                         (vio_cdrhold_mode==2'd2) ? 1'b0 : qwn_rxcdrhold;
wire qwn_txinhibit_eff = (vio_txinh_mode ==2'd1) ? 1'b1 :
                         (vio_txinh_mode ==2'd2) ? 1'b0 : qwn_txinhibit;
// Tier-1 SFP control. qwn_tx_dis = tx_word_stream sfp_disable (1 during the
// dark/laser-off phase). [Comment fixed: an older note here said "DARKW=0 ->
// laser stays enabled" -- DARKW is 2048 in all current instances, but lanes
// 0/1 run the #31 INHIBIT-ONLY policy below, so qwn_tx_dis is deliberately
// NOT wired to the pin.] VIO can force laser OFF/ON for characterization.
wire        qwn_tx_dis;         // driven by tx_word_stream (declared at fabric)
// *** INHIBIT-ONLY BUILD #31 (decisive bisect: power-cycle vs transition-loss)
// Fabric default keeps the SFP laser ON (1'b0); dark phase is signaled to
// the GT by TX_INHIBIT (gt0_txinhibit_i below) instead -- serializer
// squelched, no transitions, but laser stays emitting CW. VIO force-OFF
// (mode=1) still works for bench control.
wire sfp0_txdis_eff = (vio_txdis_mode==2'd1) ? 1'b1 :
                      (vio_txdis_mode==2'd2) ? 1'b0 : 1'b0;
   assign SFP0_TX_DISABLE = sfp0_txdis_eff;
   assign SFP0_RS0        = 1'b1;   // full line rate (SFF rate-select high)
   assign SFP0_RS1        = 1'b1;   // full line rate (drive both, not floating)
   assign ALWAYS_ON       = 1'b1;   // static 1.8V source (mezzanine -> SMA)
// SFP status: 2-FF sync into free-running drpclk + sticky latch (catches a
// transient fault/LOS between JTAG polls; cleared by VIO vio_stat_clr).
// FPGA basics -- the 2-FF synchronizer: an async input sampled near a clock
// edge can leave the first FF metastable; the second FF gives it a full
// cycle to resolve before anything fans out. ASYNC_REG="TRUE" tells Vivado
// to (a) keep the pair, (b) pack both FFs into one slice so the settle
// window is maximal, (c) exempt the crossing from normal STA. Single-BIT
// signals only -- a multi-bit bus through 2-FF pairs can tear (bits resolve
// on different cycles); buses here are either gray-ish/slow or accepted-torn.
wire        vio_stat_clr;
(* ASYNC_REG="TRUE" *) reg [1:0] tf_s, ls_s, ma_s, ma2_s, ma3_s, ma4_s;
(* ASYNC_REG="TRUE" *) reg [1:0] rxfd_s;   // gt0_rxfsmresetdone -> drpclk sync
wire auto_gt_reset;                         // autonomous GT-init-on-LOS pulse
reg tf_stk, ls_stk;
always @(posedge drpclk_in_i) begin
   tf_s  <= {tf_s[0],  SFP0_TX_FAULT};
   ls_s  <= {ls_s[0],  SFP0_RX_LOS};
   rxfd_s<= {rxfd_s[0],gt0_rxfsmresetdone_i};   // -> gt_reset_on_los
   ma_s  <= {ma_s[0],  SFP0_MOD_ABS};
   ma2_s <= {ma2_s[0], SFP2_MOD_ABS};
   ma3_s <= {ma3_s[0], SFP3_MOD_ABS};
   ma4_s <= {ma4_s[0], SFP4_MOD_ABS};
   if (vio_stat_clr) begin tf_stk<=1'b0; ls_stk<=1'b0; end
   else begin
      if (tf_s[1]) tf_stk<=1'b1;
      if (ls_s[1]) ls_stk<=1'b1;
   end
end
// {modabs4, modabs3, modabs2, modabs1, los_sticky, los_live, fault_sticky, fault_live}
// (1=cage empty per SFF; Mod1/P3 is our active lane). 8b -> no VIO reconfig.
wire [7:0] sfp_stat = {ma4_s[1], ma3_s[1], ma2_s[1], ma_s[1],
                       ls_stk, ls_s[1], tf_stk, tf_s[1]};
   assign gt0_rxcdrhold_i = qwn_rxcdrhold_eff;
   // *** INHIBIT-ONLY BUILD #31: lanes 0/1 dark = GT serializer squelch
   // (TX_INHIBIT) ONLY -- laser stays ON (SFP*_TX_DISABLE tied 0 above).
   // Removes the optical power-cycle / laser turn-on transient that 5
   // prior dark builds (all failing fid==hd/HV=0) implicate; tests whether
   // the killer is the AGC/EQ re-acquire after laser-off vs the no-edge
   // transition gap. Recovers => Fix C (GT RX reset on dark->light) is the
   // right fix. Still fails => architectural rethink. Revert: change to
   // 1'b0 here AND restore qwn_tx_dis in sfp0_txdis_eff above.
   assign gt0_txinhibit_i = qwn_txinhibit_eff;
   assign soft_reset_vio_i = vio_soft_reset;

assign  gt1_rxcdrhold_i                      =  qwn1_rxcdrhold;  // lane-1 fabric
assign  gt1_txinhibit_i                      =  qwn1_txinhibit;  // #31 inhibit-only: serializer squelch, laser stays ON

assign  gt2_rxcdrhold_i                      =  tied_to_ground_i;
assign  gt2_txinhibit_i                      =  tied_to_ground_i;

assign  gt3_rxcdrhold_i                      =  tied_to_ground_i;
assign  gt3_txinhibit_i                      =  tied_to_ground_i;
//------------------------------------------------------



    // assign resets for frame_gen modules
    assign  gt0_tx_system_reset_c = !gt0_txfsmresetdone_r2;
    assign  gt1_tx_system_reset_c = !gt1_txfsmresetdone_r2;
    assign  gt2_tx_system_reset_c = !gt2_txfsmresetdone_r2;
    assign  gt3_tx_system_reset_c = !gt3_txfsmresetdone_r2;

    // assign resets for frame_check modules
    assign  gt0_rx_system_reset_c = !gt0_rxfsmresetdone_r2;
    assign  gt1_rx_system_reset_c = !gt1_rxfsmresetdone_r2;
    assign  gt2_rx_system_reset_c = !gt2_rxfsmresetdone_r2;
    assign  gt3_rx_system_reset_c = !gt3_rxfsmresetdone_r2;

//-------------------------------------------------------------

assign gt0_drpaddr_i = 9'd0;
assign gt0_drpdi_i = 16'd0;
assign gt0_drpen_i = 1'b0;
assign gt0_drpwe_i = 1'b0;
assign gt1_drpaddr_i = 9'd0;
assign gt1_drpdi_i = 16'd0;
assign gt1_drpen_i = 1'b0;
assign gt1_drpwe_i = 1'b0;
assign gt2_drpaddr_i = 9'd0;
assign gt2_drpdi_i = 16'd0;
assign gt2_drpen_i = 1'b0;
assign gt2_drpwe_i = 1'b0;
assign gt3_drpaddr_i = 9'd0;
assign gt3_drpdi_i = 16'd0;
assign gt3_drpen_i = 1'b0;
assign gt3_drpwe_i = 1'b0;

// Autonomous two-board bring-up: re-pulse the GT init while lane-0/SFP0 has
// light (RX_LOS deasserted) but the RX startup FSM is not yet done. Gated on
// gt0 only (RX board's lane-1 cage is empty -> would retry forever). Self-
// limiting + non-disruptive. Inputs drpclk-synced (ls_s, rxfd_s above).
gt_reset_on_los u_gt_reset_on_los
  (.clk(drpclk_in_i), .rst(1'b0),
   .los_present(~ls_s[1]), .rxfsm_done(rxfd_s[1]),
   .soft_reset(auto_gt_reset));

generate
if (EXAMPLE_USE_CHIPSCOPE==1)
begin : chipscope
assign soft_reset_i = soft_reset_vio_i | auto_gt_reset;  // VIO OR autonomous
end //end EXAMPLE_USE_CHIPSCOPE=1 generate section
else 
begin: no_chipscope 
assign soft_reset_i = tied_to_ground_i;
end
endgenerate //End generate for EXAMPLE_USE_CHIPSCOPE
// vio core insertion for driving soft_reset_i
































































































































//============================ QWN FABRIC (lane 0) ============================
   // qwn_rxcdrhold / qwn_txinhibit declared at the retargeted tie-off site
   // Rate-matched per-clock TX word streamer (replaces tx_burst_seq +
   // enc_8b10b + tx_gearbox + qwn_header_rom). One ready 64-bit word per
   // txusrclk2 -> the GT (consumes gt0_txdata every cycle) gets a continuous,
   // correctly-paced stream. Burst pre-encoded by work/gen_tx_words.py into
   // qwn_tx_words.mem (660 words: warmup4096 + settle32 + fid + hdr+payload).
   // Sim-validated in tb_tx_path under the faithful GT model (TXPATH_PASS:
   // 31/31 headers, 0.16% code err). Fixes the TX rate mismatch AND the
   // tx_burst_seq duplicate-SOH off-by-one (no runtime prefetch pipeline).
   wire [63:0] qwn_txword;  wire qwn_fid_stb;  // qwn_tx_dis declared in SFP ctrl block above
   // DARKW>0: internal periodic burst -> after the laser-on header the
   // streamer enters a DARK phase (sfp_disable/tx_inhibit high = laser OFF)
   // for DARKW txusrclk2 cycles (protection + inter-burst quiet) then wraps
   // and re-bursts. [Comment fixed: "dark_period_ctrl" is gone -- RXCDRHOLD
   // across the dark is now owned by rxcdrhold_ctrl inside qwn_rx_lane, B7
   // HOLD_FOREVER policy.] The gate logic free-runs the marker count through
   // the laser-off gap (gate_delay cycles from the FID, no data needed).
   // DARKW tunable; 2048 words ~= 105 us dark, ~38 kHz burst rate.
   tx_word_stream #(.NW(660),.FIDW(645),.GUARDW(256),.DARKW(2048),.MEM("qwn_tx_words.mem"))
     u_qwn_txw
     (.clk(gt0_txusrclk2_i),.rst(gt0_tx_system_reset_c),
      .word_o(qwn_txword),.fid_stb(qwn_fid_stb),
      .tx_inhibit(qwn_txinhibit),.sfp_disable(qwn_tx_dis));
   assign gt0_txdata_i        = qwn_txword;
   assign gt0_txdata_float16_i= 16'd0;
   assign gt3_txdata_i = 64'd0;  // gt3 spare
   // ---- Lane-2 (gt2 / cage-2) TX-ONLY: emits the QWN datagram into the
   //  INTER-BOARD link (C16A cage-2 -> C6A SFP0; C6A's gt0/lane-0 recovers
   //  it with the existing instrumented logic). CLOCK-SAFE: clocked by
   //  gt0_txusrclk2_i -- the clock gt2 already piggybacks (GT2_TXUSRCLK2 =
   //  gt0_txusrclk2) -> NO new MMCM/clock -> no clock-region X1Y3 overflow
   //  (the full-3rd-lane attempt failed exactly on the 12-clock/region cap).
   wire [63:0] qwn2_txword;  wire qwn2_fid_stb;  wire qwn2_tx_dis;
   tx_word_stream #(.NW(660),.FIDW(645),.GUARDW(256),.DARKW(2048),.MEM("qwn_tx_words.mem"))
     u_qwn2_txw
     (.clk(gt0_txusrclk2_i),.rst(gt0_tx_system_reset_c),
      .word_o(qwn2_txword),.fid_stb(qwn2_fid_stb),
      .tx_inhibit(),.sfp_disable(qwn2_tx_dis));
   assign gt2_txdata_i        = qwn2_txword;
   assign gt2_txdata_float16_i= 16'd0;
   // cage-2 SFP switch control (gt2/Mod3). [Comment fixed: previously said
   // "laser ON (DARKW=0)"; DARKW=2048 now, so qwn2_tx_dis pulses every burst
   // and the cage-2 laser REALLY turns off during the dark gap -- this is
   // the deployed detector-protection mechanism on the inter-board link.
   // Note gt2's tx_inhibit is unconnected: laser-off IS its dark signaling.]
   assign SFP3_TX_DISABLE = qwn2_tx_dis;     // AC38
   assign SFP3_RS0        = 1'b1;            // AD42 full line rate
   // TX-side payload-start reference (INTRA-channel jitter): gt2 TX datagram
   // fiducial -> H31. jitter of (C6A recovered marker - this) = intra-channel
   // (offset-invariant: the constant fid->payload gate_delay calibrates out).
   assign TX_PAYLOAD_REF  = qwn2_fid_stb;    // H31

   // RX fabric
   wire [7:0]  qwn_rb;  wire [3:0] qwn_rc, qwn_reph;
   wire [7:0]  qwn_byte; wire qwn_k, qwn_byv, qwn_ce, qwn_lock;
   wire        qwn_fidp, qwn_hv, qwn_hd; wire [7:0] qwn_dst;
   wire [15:0] qwn_pd;  wire [23:0] qwn_gd; wire qwn_gate; wire [7:0] qwn_gf;
   wire [2:0] qwn_gi;   // committed inst eph (borrow + hist)
   wire qwn_veto;       // phase-disagreement marker suppression (diag)
   // (CDR re_arm experiment removed -- the real periodic-dark fix is the
   //  continuous comma RE-ALIGN in rx_frame_par, sim-validated tb_realign.)
   // P4: the full RX recovery fabric (oversample CDR + frame_par + header +
   //  gate + per-burst RXCDRHOLD) is now encapsulated in qwn_rx_lane. The
   //  surrounding per-lane wiring below (VIO rxcdrhold override, pin assigns,
   //  dbg counters, ILA) is unchanged -- this just drives the same wires.
   //
   // Port semantics worth knowing (each maps to a campaign build; full story
   // in docs/CAMPAIGN_BRIEF_2026-06.md):
   //   reph / ui_offset : LIVE oversampler edge phase (eph, 100 ps units,
   //       8 samples per 800 ps UI) and LIVE symbol-end slot k within the
   //       64-bit word (Build A detection: per-burst CDR/divider re-lock
   //       lands the byte stream on a random UI slot 0..7 -> the marker
   //       would inherit an integer-UI offset; these observables proved it).
   //   gate_ui : ui_offset COMMITTED at gate arm (B4). FPGA discipline
   //       invented here -- the "commit latch": rx_header re-latches on
   //       EVERY fid_ok, including false fiducials decoded from dark-gap
   //       garbage ~2200 cycles before the gate fires; sampling the live
   //       register at fire time used the dark value. Latch ONCE when the
   //       validated header arms the gate; ignore everything after.
   //   gate_fine : ODELAY trim, B8 SPLIT-ROLE value = filtered eph estimate
   //       ANCHORED to the burst's instantaneous frame. The BORROW decision
   //       stays on instantaneous eph (correlated with the framer's k);
   //       filtering the borrow decorrelates it -> +-800 ps flips (proved
   //       by jitter A/B sim tb_eph_jitter, not intuition).
   //   gate_inst : committed INSTANTANEOUS eph (borrow input + histogram).
   //   gate_veto : marker suppressed on inst-vs-filtered disagreement.
   //       B9 (TH=24=150 ps) was a measured NEGATIVE: 14.75% vetoed for zero
   //       sigma gain -- large disagreement is the filter WORKING. B11 keeps
   //       veto at TH=48 (300 ps = genuinely wrap-ambiguous; ~1% expected).
   //       "Missing gate, never a wrong gate" makes suppression acceptable.
   //   rxcdrhold : B7 HOLD_FOREVER policy -- hold the GT CDR permanently
   //       after the first fiducial; release only on SUSTAINED comma loss
   //       (~840 us; per-burst dark flicker never trips). Viable only
   //       because continuous comma re-align + per-burst ui/eph correction
   //       absorb the ppm walk that killed hold-forever in the old design.
   //   hold_blocked : B5 diag -- reopen deferred while a gate is pending
   //       (fires on ~98% of bursts, harmless; measured via idx13 below).
   wire [2:0] qwn_ui_offset;
   wire [2:0] qwn_gate_ui;     // committed FID slot (false-fid-immune)
   wire       qwn_hold_blk;    // diag: hold reopen deferred by pending gate
   qwn_rx_lane u_qwn_lane
     (.rxusrclk2(gt0_rxusrclk2_i),.rx_reset(gt0_rx_system_reset_c),
      .rxdata(gt0_rxdata_i),
      .rbits(qwn_rb),.rcnt(qwn_rc),.reph(qwn_reph),.byte_o(qwn_byte),.k_o(qwn_k),
      .byte_valid(qwn_byv),.code_err(qwn_ce),.comma_locked(qwn_lock),
      .fid_pulse(qwn_fidp),.hdr_valid(qwn_hv),.hdr_discard(qwn_hd),
      .destination(qwn_dst),.payload_dur(qwn_pd),.gate_delay(qwn_gd),
      .gate(qwn_gate),.gate_fine(qwn_gf),.gate_inst(qwn_gi),.gate_veto(qwn_veto),.gate_ui(qwn_gate_ui),
      .rxcdrhold(qwn_rxcdrhold),.hold_blocked(qwn_hold_blk),
      .ui_offset(qwn_ui_offset));
   assign gt0_track_data_i = qwn_lock;       // -> support gt0_data_valid_in
   assign gt2_track_data_i = 1'b1;
   assign gt3_track_data_i = 1'b1;
   assign gt0_rxslide_i    = 1'b0;
   assign gt1_rxslide_i    = 1'b0;
   assign gt2_rxslide_i    = 1'b0;
   assign gt3_rxslide_i    = 1'b0;
   assign track_data_out_i = qwn_gate;       // lane-0 gate -> TRACK_DATA_OUT
   // RX_PAYLOAD_MARK_SIGNAL/_IDLER driven by the sub-UI FINE marker block
   // below (after BOTH lanes' signals are declared) -- see u_qwn_idelayctrl.

//================ TIER-2 DOWNSTREAM EXPERIMENT I/O (P2, lane 0) =============
// Recovered {destination, payload-start marker, payload_dur, fiducial} drive
// the app-layer experiment blocks (verbatim from the buffered reference,
// kept datapath-agnostic). DEBUG-OBSERVE build: NO new physical pins --
// pin/connector commit deferred until the downstream logic is confirmed on
// HW. All in lane-0 RXUSRCLK2.
// [Comment fixed: an older note said outputs go to "VIO probe_in25/26" --
// the VIO has 25 inputs (in0..in24) and probe_in17, the slot Tier-2 once
// borrowed, was re-repurposed for the phase histogram during the jitter
// campaign. qwn_tier2_stat/qwn_tier2_active below are currently CONNECTED
// TO NOTHING (synthesis prunes them); re-attach to a probe when Tier-2
// observation resumes. Logic kept so the wiring/CDC intent is preserved.]
   // recovered destination byte -> 2-bit routing switch select
   wire [1:0] qwn_switch_ctrl;
   switch_controller u_qwn_switch
     (.clock_in(gt0_rxusrclk2_i),.destination(qwn_dst),
      .switch_control(qwn_switch_ctrl));
   // payload-start marker + payload_dur -> photon-detector TDC interface
   wire qwn_ttl_payload, qwn_ttl_tdcclk, qwn_ttl_4mhz, qwn_ttl_trig;
   // PROVISIONAL guards (debug-observe): defaults (2000/500) are the buffered
   // design's scale and dwarf our recovered payload_dur(=0x40); these open a
   // window for pd>16. Replace with the experiment's real values.
   qwn_ttl_rx #(.guard_time_pre(22'd8),.guard_time_post(22'd8),
                .tdc_clock_4M(22'd20),.DIVISOR_trigger(22'd225750))
     u_qwn_ttl_rx
     (.clock_in(gt0_rxusrclk2_i),.start_count(qwn_gate),.payload_dur(qwn_pd),
      .payload(qwn_ttl_payload),.tdc_clock(qwn_ttl_tdcclk),
      .divided_4mhz_clock(qwn_ttl_4mhz),.trgr_dca(qwn_ttl_trig));
   // PROVISIONAL recovered-data mapping (debug-observe; confirm w/ user):
   //   header_start=fiducial(qwn_fidp), header_stop=payload-marker(qwn_gate),
   //   header_dur=payload_dur. DIVISOR_HDR_SW = provisional rx-switch delay.
   localparam [31:0] DIVISOR_HDR_SW = 32'd64;
   wire qwn_recv_sw0;
   receiverSwitchStateMachine u_qwn_rsm
     (.clk(gt0_rxusrclk2_i),.reset(gt0_rx_system_reset_c),
      .header_start(qwn_fidp),.header_stop(qwn_gate),
      .header_dur({48'd0,qwn_pd}),.DIVISOR_header_sw(DIVISOR_HDR_SW),
      .receiver_sw_0(qwn_recv_sw0));
   // Tier-2 observe pack: live state bits + slow event counters. (Counters
   // are slow free-running/per-burst, so a VIO's async drpclk sample would
   // be benign for debug.) [Comment fixed: currently UNCONNECTED -- see the
   // Tier-2 banner above; the probe slot it used was taken by the campaign.]
   reg [11:0] t2_sw_cnt, t2_trig_cnt;
   reg        qwn_trig_q; reg [1:0] qwn_sw_q;
   always @(posedge gt0_rxusrclk2_i) begin
     if (gt0_rx_system_reset_c) begin
        t2_sw_cnt<=12'd0; t2_trig_cnt<=12'd0; qwn_trig_q<=1'b0; qwn_sw_q<=2'd0;
     end else begin
        qwn_trig_q <= qwn_ttl_trig; qwn_sw_q <= qwn_switch_ctrl;
        if (qwn_switch_ctrl != qwn_sw_q) t2_sw_cnt   <= t2_sw_cnt   + 12'd1;
        if (qwn_ttl_trig & ~qwn_trig_q)  t2_trig_cnt <= t2_trig_cnt + 12'd1;
     end
   end
   wire [31:0] qwn_tier2_stat =
        {t2_trig_cnt,                 // [31:20] trigger-edge count
         t2_sw_cnt,                   // [19:8]  switch-change count
         qwn_switch_ctrl,             // [7:6]   live routing select
         qwn_recv_sw0,                // [5]     receiver switch
         qwn_ttl_trig,                // [4]
         qwn_ttl_4mhz,                // [3]
         qwn_ttl_tdcclk,              // [2]     gated TDC clock
         qwn_ttl_payload,             // [1]     payload window
         1'b0};                       // [0]
   wire qwn_tier2_active = qwn_ttl_payload | qwn_recv_sw0 | (|qwn_switch_ctrl);
//==========================================================================

//============================ QWN FABRIC (lane 1) ===========================
// Exact mirror of lane 0 on the gt1 channel (cross-SFP loopback TX1<->RX2 /
// TX2<->RX1: the user fibers the two SFP cages; the FPGA just runs both
// lanes' TX + RX + marker). Lane 0 above is bit-identical & HW-proven; this
// is a parallel copy -> zero regression on lane 0. Same qwn_tx_words.mem
// (both lanes transmit the same datagram; the experiment compares the two
// recovered payload-start markers). qwn1_gate = lane-1 marker (Inc4 -> pin).
   wire [63:0] qwn1_txword;  wire qwn1_fid_stb;  wire qwn1_tx_dis;
   tx_word_stream #(.NW(660),.FIDW(645),.GUARDW(256),.DARKW(2048),.MEM("qwn_tx_words.mem"))
     u_qwn1_txw
     (.clk(gt1_txusrclk2_i),.rst(gt1_tx_system_reset_c),
      .word_o(qwn1_txword),.fid_stb(qwn1_fid_stb),
      .tx_inhibit(qwn1_txinhibit),.sfp_disable(qwn1_tx_dis));
   assign gt1_txdata_i        = qwn1_txword;
   assign gt1_txdata_float16_i= 16'd0;

   wire [7:0]  qwn1_rb;  wire [3:0] qwn1_rc, qwn1_reph;
   wire [7:0]  qwn1_byte; wire qwn1_k, qwn1_byv, qwn1_ce, qwn1_lock;
   wire        qwn1_fidp, qwn1_hv, qwn1_hd; wire [7:0] qwn1_dst;
   wire [15:0] qwn1_pd;  wire [23:0] qwn1_gd; wire qwn1_gate; wire [7:0] qwn1_gf;
   wire [2:0] qwn1_gi;
   // P4: encapsulated RX fabric (see lane 0). Identical block, gt1 domain.
   wire [2:0] qwn1_ui_offset;
   qwn_rx_lane u_qwn1_lane
     (.rxusrclk2(gt1_rxusrclk2_i),.rx_reset(gt1_rx_system_reset_c),
      .rxdata(gt1_rxdata_i),
      .rbits(qwn1_rb),.rcnt(qwn1_rc),.reph(qwn1_reph),.byte_o(qwn1_byte),
      .k_o(qwn1_k),.byte_valid(qwn1_byv),.code_err(qwn1_ce),
      .comma_locked(qwn1_lock),.fid_pulse(qwn1_fidp),.hdr_valid(qwn1_hv),
      .hdr_discard(qwn1_hd),.destination(qwn1_dst),.payload_dur(qwn1_pd),
      .gate_delay(qwn1_gd),.gate(qwn1_gate),.gate_fine(qwn1_gf),.gate_inst(qwn1_gi),.gate_veto(),.gate_ui(),
      .rxcdrhold(qwn1_rxcdrhold),.hold_blocked(),
      .ui_offset(qwn1_ui_offset));
   assign gt1_track_data_i = qwn1_lock;      // -> support gt1_data_valid_in

   // ================ sub-UI FINE marker placement (both lanes) ==============
   // Placed AFTER both lanes' signals are declared (qwn_* and qwn1_*). The
   // coarse gate fires on a rxusrclk2 edge and discards the 8x oversample
   // sub-bit phase (eph) -- up to ~700 ps of burst-to-burst quantization at
   // 10G/1.25G (the CDR phase that IS the intra-channel jitter). ODELAYE2
   // delays each marker edge by gate_fine to land it at the true payload-start
   // sub-UI position. IDELAYCTRL calibrates the taps [comment fixed: its
   // REFCLK is idelay_ref200 from the MMCM below -- drpclk_in_i is NOT
   // 200 MHz]; one controller for the qwn_mark_grp ODELAYs (auto-replicated
   // per bank).
   // The stable/DRP clock is 156.25 MHz -- BELOW the IDELAYCTRL's ~200 MHz
   // spec (and there is no 200 MHz clock in the design). Synthesize an exact
   // 200 MHz from it with a dedicated MMCM: 156.25 x 8 / 6.25 = 200 (VCO 1250).
   //
   // FPGA basics -- IDELAYCTRL/ODELAYE2 calibration: ODELAYE2's 32 delay taps
   // are uncalibrated analog delay elements; IDELAYCTRL continuously trims
   // them against its REFCLK so one tap = 1/(32*2*Fref) = 78.125 ps at
   // 200 MHz, across voltage/temperature. Feed it the wrong frequency and
   // every "78 ps" trim is silently scaled. The (* IODELAY_GROUP *) attribute
   // (on the IDELAYCTRL below and on the ODELAYE2s inside mark_odelay) tells
   // the tools WHICH delay primitives this controller calibrates, so
   // placement keeps controller and delays in legal banks (and replicates
   // the controller per bank if the group spans banks).
   //
   // FPGA basics -- MMCM feedback choice: this MMCM uses INTERNAL feedback
   // (CLKFBOUT wired straight to CLKFBIN, no BUFG). That means CLKOUT0 is
   // NOT phase-aligned to CLKIN1 -- and that is fine HERE because IDELAYCTRL
   // only needs the *frequency*; nobody crosses between drpclk and
   // idelay_ref200 synchronously. Contrast with the GT user-clock MMCMs
   // (CLOCK_MODULE in the generated support files): those route CLKFBOUT
   // through a BUFG to CLKFBIN, so the MMCM's phase detector servoes the
   // FED-BACK (post-BUFG) edge onto CLKIN -- the BUFG insertion delay is
   // driven to zero as seen at the fabric FFs ("deskew"), making CLKOUTn at
   // the flops align with CLKIN at the MMCM pin. Use BUFG feedback when
   // consumers must be phase-related to the source; internal feedback when
   // only frequency matters (lower jitter, saves a BUFG).
   wire mmcm_fb, idelay_ref200_pre, idelay_ref200, mmcm_locked;
   MMCME2_BASE #(
     .BANDWIDTH("OPTIMIZED"), .CLKIN1_PERIOD(6.400),
     .CLKFBOUT_MULT_F(8.000),  .DIVCLK_DIVIDE(1),
     .CLKOUT0_DIVIDE_F(6.250), .CLKOUT0_DUTY_CYCLE(0.5), .CLKOUT0_PHASE(0.0),
     .STARTUP_WAIT("FALSE")
   ) u_idelay_mmcm (
     .CLKIN1(drpclk_in_i), .CLKFBIN(mmcm_fb), .CLKFBOUT(mmcm_fb),
     .CLKOUT0(idelay_ref200_pre),
     .LOCKED(mmcm_locked), .PWRDWN(1'b0), .RST(1'b0)
   );
   BUFG u_idelay_ref_bufg (.I(idelay_ref200_pre), .O(idelay_ref200));

   // hold IDELAYCTRL reset until the 200 MHz MMCM is locked + >60 ns
   reg [5:0] idc_rst_cnt = 6'd0;
   reg       idc_rst     = 1'b1;
   always @(posedge drpclk_in_i) begin
      if (!mmcm_locked) begin idc_rst_cnt <= 6'd0; idc_rst <= 1'b1; end
      else if (idc_rst_cnt != 6'd63) begin idc_rst_cnt <= idc_rst_cnt + 6'd1; idc_rst <= 1'b1; end
      else idc_rst <= 1'b0;
   end
   wire idc_rdy;
   (* IODELAY_GROUP = "qwn_mark_grp" *)
   IDELAYCTRL u_qwn_idelayctrl (.REFCLK(idelay_ref200),.RST(idc_rst),.RDY(idc_rdy));

   // ---- Build B (fix #3): integer-UI slot placement, LANE 0 / N41 ONLY ----
   // The coarse gate inherits the per-burst 8-UI CDR re-lock mode (800 ps
   // stripes, HW-confirmed near-uniform 0..7, p_a 2026-06-09). OSERDESE2
   // (DDR 8:1, 625 MHz) re-launches the marker with its rising edge AT slot
   // ui_offset -> the 8 stripes collapse; ODELAYE2 eph trim then cascades
   // (OSERDES.OQ -> ODELAY.ODATAIN, dedicated OLOGIC path, same N41 tile).
   // Sim: tb_mark_oserdes (slot grid exact) + tb_uioff_e2e (tracks a 0..15 UI
   // stream shift at 800 ps/UI exactly, sign direct). Lane 1 / H41 stays on
   // the old coarse+ODELAY path = on-bench A/B reference.
   //
   // FPGA basics -- OSERDESE2 in this role (first GT-adjacent OLOGIC use in
   // the design; details in mark_oserdes.v):
   //  * DDR 8:1 mode: CLKDIV (156.25 MHz) loads an 8-bit word, CLK (625 MHz)
   //    shifts it out on both edges -> one bit per 800 ps = one bit per UI.
   //    D1 is the FIRST bit on the wire, so "slot k" = a 1 placed at D(k+1).
   //  * CLK/CLKDIV pairing rule: both must come from the same source with a
   //    fixed integer ratio AND matched insertion; the word transfer from
   //    the CLKDIV register into the CLK-domain shifter happens INSIDE the
   //    hard macro and has NO STA PATH -- the timing report literally cannot
   //    show this margin (verified absent). Skew between the two BUFG trees
   //    eats it silently: the bench saw intermittent HALF-WORD (3.2 ns)
   //    output slips before the CLOCK_DELAY_GROUP constraint matched the
   //    trees (see qwn_bufferless.xdc, B4 note).
   //  * TQ/tristate pitfall (cost us Build B -- pad dead on HW, every sim
   //    green): the IOB's tristate control is OSERDES's TQ register. With
   //    TCE=0 + INIT_TQ=1 it powers up driving "Hi-Z" FOREVER. The unisim
   //    model drives OQ regardless of TQ, so simulation cannot catch it.
   //    B2 fix inside mark_oserdes: TCE=1, T1=0, INIT_TQ/SRVAL_TQ=0.
   //  * OQ -> ODELAYE2.ODATAIN is a dedicated OLOGIC route within the same
   //    IOB tile (the DDR3-write-leveling style path) -- the eph trim
   //    cascades after slot placement with no fabric detour.
   //
   // [B2..B9 history -- SUPERSEDED by B10 below, kept for the record]:
   // Clocks were one extra MMCM off the lane-0 recovered clock, BUFG-deskewed
   // feedback -> mk156 phase-aligned + RELATED to rxusrclk2 (both in the
   // gt_refclk generated-clock group): gate/ui capture inside mark_oserdes
   // was a timed FF-FF path. VCO = 156.25 x 8 = 1250 (600-1440 ok); 625 MHz
   // on a BUFG (-2 ceiling ~710); zero fabric logic in the 625 domain.
   //
   // B10 DE-CASCADE (current): the OSERDES clock pair comes from the SAME RX
   // MMCM that makes rxusrclk2 (gt0 rxoutclk_mmcm1 in the EDITED GENERATED
   // clock_test_gt_usrclk_source.v: 312.5 MHz RXOUTCLKPMA in, MULT 2.0 ->
   // VCO exactly 625 MHz; CLK2_OUT divide-1 = 625 was sitting unused and
   // already BUFG'd inside CLOCK_MODULE). Removes the cascaded marker MMCM
   // (its VCO phase noise + its tracking lag behind the recovered clock --
   // a cascade re-converges through TWO loop filters) AND deletes the
   // rxusrclk2->mk156 capture crossing entirely: the word builder now runs
   // in rxusrclk2 itself, 3 BUFGs freed. mk_locked := the RX MMCM lock.
   // Targets the ~50-60 ps unattributed term in the B8 jitter budget; B11
   // JTAG-validated, analog verdict pending (task #40).
   wire mk_locked = gt0_rxmmcm_lock_i;
   wire qwn_mark_osq;
   wire [21:0] mk_fire_cnt;        // capture-FF gate count (hist idx14 diag)
   mark_oserdes u_qwn_mark_os
     (.clk156(gt0_rxusrclk2_i), .clk625(gt0_rxusrclk625_i),
      .rst(gt0_rx_system_reset_c | ~mk_locked),
      .gate_in(qwn_gate), .ui_offset(qwn_gate_ui), .eph_in(qwn_gi),
      .locked(mk_locked),
      .oq(qwn_mark_osq), .fire_cnt(mk_fire_cnt));

   wire qwn_mark_dly, qwn1_mark_dly;
   mark_odelay u_qwn_mark_od        // lane-0: slot-placed marker -> eph trim -> N41
     (.clk(gt0_rxusrclk2_i),.rst(gt0_rx_system_reset_c),
      .gate_in(qwn_mark_osq),.gate_fine(qwn_gf),.fid(qwn_fidp),.gate_dly(qwn_mark_dly));
   mark_odelay u_qwn1_mark_od       // lane-1 idler marker -> H41
     (.clk(gt1_rxusrclk2_i),.rst(gt1_rx_system_reset_c),
      .gate_in(qwn1_gate),.gate_fine(qwn1_gf),.fid(qwn1_fidp),.gate_dly(qwn1_mark_dly));
   // OPEN observation (task #40): N41 shows a ~52 ns pulse on the scope vs
   // the 6.4 ns RTL gate width -- post-OSERDES width mystery, unexplained.
   // The RISING edge (the only timed edge) is unaffected; jitter figures ok.
   assign RX_PAYLOAD_MARK_SIGNAL = qwn_mark_dly;  // lane-0 marker (sub-UI) -> N41
   assign RX_PAYLOAD_MARK_IDLER  = qwn1_mark_dly; // lane-1 marker (sub-UI) -> H41
   // =========================================================================

   // ============ on-chip sub-UI phase HISTOGRAM (ODELAY-free measure) ========
   // Bin the per-burst committed eph (gate_inst; the value the trim/borrow
   // logic actually used) over validated bursts -> the 8-bin distribution =
   // the intra-channel sub-UI phase at 100 ps resolution, read with NO
   // instrument (loopback: TX phase fixed, so all motion is recovery jitter).
   // A 4-bit index {lane,bin} self-cycles (~27 ms/step) so all 16 counts
   // surface on probe_in17 over a few seconds of polling.
   // [Comment fixed: the pack is NOT {idx,count[27:0]} anymore -- see the
   //  "probe_in17 pack" note below for the current Build-A layout.]
   // POLLING GOTCHA (cost a debug session): the index steps every ~26.8 ms;
   // if the Tcl poll cadence is not MUCH faster than that, you alias --
   // bins repeat/skip and coverage of all 16 indices silently fails.
   reg [3:0]  hist_idx = 4'd0;
   reg [21:0] hist_div = 22'd0;
   always @(posedge drpclk_in_i) begin
      hist_div <= hist_div + 22'd1;
      if (&hist_div) hist_idx <= hist_idx + 4'd1;
   end
   wire [27:0] hist_c0, hist_c1;
   phase_hist #(.CW(28)) u_qwn_hist        // lane-0 recovered phase
     (.clk(gt0_rxusrclk2_i),.rst(gt0_rx_system_reset_c),
      .fine({1'b0,qwn_gi}),.stb(qwn_hv),.rsel(hist_idx[2:0]),.rcount(hist_c0));
   phase_hist #(.CW(28)) u_qwn1_hist       // lane-1 recovered phase
     (.clk(gt1_rxusrclk2_i),.rst(gt1_rx_system_reset_c),
      .fine({1'b0,qwn1_gi}),.stb(qwn1_hv),.rsel(hist_idx[2:0]),.rcount(hist_c1));
   // probe_in17 pack (Build A): {idx[31:28], ui0[27:25], ui1[24:22], count[21:0]}
   // Each poll surfaces the live ui_offset (lane-0/1) AND a phase-hist bin.
   // Hist counter narrowed 28b -> 22b (~4M = several minutes runway, ample).
   // Build B: idx==15 (lane-1 bin 7, dark/unused on bench) repurposed as the
   // marker-clock diagnostic: count[0] = mk_locked ("N41 dead? check bin15").
   // [Since B10 mk_locked = the gt0 RX MMCM lock -- the marker MMCM is gone.]
   // idx==14 (lane-1 bin 6, dark) = mark_oserdes fire count: did the gate
   // capture FF actually see each gate pulse? (async-sampled, torn reads ok)
   // B6 occurrence counters (which defensive fixes actually FIRE on HW --
   // both fixes produced no bench change, so measure their event rates):
   // idx==13 = hold reopen-blocked events; idx==12 = stale-ui events
   // (gate fired while live ui_offset != committed gate_ui).
   //
   // CONSOLIDATED idx map + the B6 measured answers (3.1M-burst run):
   //   idx 0..7  : lane-0 eph histogram bins 0..7 (100 ps each)
   //   idx 8..10 : lane-1 (dark) eph bins 0..2 -- still real bins
   //   idx 11    : B9 veto count       -- measured 14.75% at TH=24 (the
   //               negative result that retuned B11 to TH=48, ~1% expected)
   //   idx 12    : stale-ui events     -- measured 0.03% (mechanism real,
   //               rare; B4 fix correct but not the straggler source)
   //   idx 13    : hold reopen-blocked -- measured ~98% of bursts
   //               (ubiquitous and harmless; B5 deferral does its job)
   //   idx 14    : mark_oserdes fire_cnt vs header count -- measured
   //               markers/validated-header = 1.0000 (no lost/extra fires)
   //   idx 15    : marker-clock locked (bit 0)
   // Methodology note: occurrence counters are how a defensive fix that
   // produced NO histogram change was still verified real (B4/B5) -- count
   // the mechanism directly instead of inferring from the jitter figure.
   reg [21:0] mk_stale_cnt, mk_hblk_cnt, mk_veto_cnt;
   reg        hblk_q;
   always @(posedge gt0_rxusrclk2_i) begin
      if (gt0_rx_system_reset_c) begin
         mk_stale_cnt<=22'd0; mk_hblk_cnt<=22'd0; mk_veto_cnt<=22'd0; hblk_q<=1'b0;
      end else begin
         hblk_q <= qwn_hold_blk;
         if (qwn_gate && (qwn_gate_ui != qwn_ui_offset))
            mk_stale_cnt <= mk_stale_cnt + 22'd1;
         if (qwn_hold_blk && !hblk_q)
            mk_hblk_cnt  <= mk_hblk_cnt + 22'd1;
         if (qwn_veto)
            mk_veto_cnt  <= mk_veto_cnt + 22'd1;   // B9: suppressed markers
      end
   end
   // B9: idx==11 (lane-1 bin 3, dark) = veto count (suppressed markers)
   wire [21:0] hist_cnt22 = (hist_idx == 4'd15) ? {21'd0, mk_locked}
                          : (hist_idx == 4'd14) ? mk_fire_cnt
                          : (hist_idx == 4'd13) ? mk_hblk_cnt
                          : (hist_idx == 4'd12) ? mk_stale_cnt
                          : (hist_idx == 4'd11) ? mk_veto_cnt
                          : (hist_idx[3] ? hist_c1[21:0] : hist_c0[21:0]);
   wire [31:0] qwn_phase_hist = {hist_idx, qwn_ui_offset, qwn1_ui_offset, hist_cnt22};
   // =========================================================================

   // ---- Lane-1 SFP control + status (DUPLICATE of the SFP0 Tier-1 block;
   // parameterize per-channel later). [Comment fixed: qwn1_tx_dis DOES pulse
   // per burst now (DARKW=2048), but under the #31 inhibit-only policy it is
   // intentionally NOT wired to the pin -- the fabric branch below is 1'b0,
   // lane-1 laser stays ON, dark = TX_INHIBIT squelch.] VIO force OFF/ON. ----
   wire [1:0] vio1_txdis_mode;       // probe_out6: 0=fabric 1=force-OFF 2=force-ON
   // #31 inhibit-only: laser ON always (fabric branch 1'b0, was qwn1_tx_dis)
   wire sfp1_txdis_eff = (vio1_txdis_mode==2'd1) ? 1'b1 :
                         (vio1_txdis_mode==2'd2) ? 1'b0 : 1'b0;
   assign SFP1_TX_DISABLE = sfp1_txdis_eff;
   assign SFP1_RS0        = 1'b1;    // full line rate (mirror SFP0_RS0)
   // RX_LOS 2-FF sync into drpclk + sticky (shares vio_stat_clr with lane-0).
   (* ASYNC_REG="TRUE" *) reg [1:0] ls1_s;
   reg ls1_stk;
   always @(posedge drpclk_in_i) begin
      ls1_s <= {ls1_s[0], SFP1_RX_LOS};
      if (vio_stat_clr)  ls1_stk <= 1'b0;
      else if (ls1_s[1]) ls1_stk <= 1'b1;
   end
   // lane-1 status byte: {4'b0, modabs(P2)=ma2_s[1], los_stk, los_live, 1'b0}
   // (ma2_s = SFP2_MOD_ABS sync from the SFP0 always block = the P2/gt1 cage).
   wire [7:0] sfp1_stat = {4'b0, ma2_s[1], ls1_stk, ls1_s[1], 1'b0};
//==========================================================================

//============================ QWN BRING-UP DEBUG ============================
   // CDC counters (RX events -> free-running drpclk) for VIO probe_in
   wire [31:0] dbg_good_cnt, dbg_err_cnt;
   wire [15:0] dbg_fid_cnt, dbg_hv_cnt, dbg_hd_cnt, dbg_pd_l;
   wire [7:0]  dbg_dst_l;
   wire        qwn_qplllock;
   wire        dbg_qpll;
   wire [15:0] dbg_tx_hb, dbg_rx_hb;
   qwn_dbg u_qwn_dbg (
     .rx_clk(gt0_rxusrclk2_i), .rx_rst(gt0_rx_system_reset_c),
     .ev_good(qwn_byv & ~qwn_ce), .ev_err(qwn_byv & qwn_ce),
     .ev_fid(qwn_fidp), .ev_hv(qwn_hv), .ev_hd(qwn_hd),
     .dst_i(qwn_dst), .pd_i(qwn_pd),
     .tx_clk(gt0_txusrclk2_i), .rxhb_clk(gt0_rxusrclk2_i),
     .qpll_i(qwn_qplllock),
     .drpclk(drpclk_in_i),
     .good_cnt(dbg_good_cnt), .err_cnt(dbg_err_cnt),
     .fid_cnt(dbg_fid_cnt), .hv_cnt(dbg_hv_cnt), .hd_cnt(dbg_hd_cnt),
     .dst_l(dbg_dst_l), .pd_l(dbg_pd_l),
     .qpll_l(dbg_qpll), .tx_hb(dbg_tx_hb), .rx_hb(dbg_rx_hb));

   // ---- Lane-1 telemetry (2nd qwn_dbg on gt1; DUPLICATE for now) ----
   wire [31:0] dbg1_good_cnt, dbg1_err_cnt;
   wire [15:0] dbg1_fid_cnt, dbg1_hv_cnt, dbg1_hd_cnt, dbg1_pd_l;
   wire [7:0]  dbg1_dst_l;
   wire        dbg1_qpll; wire [15:0] dbg1_tx_hb, dbg1_rx_hb;
   qwn_dbg u_qwn1_dbg (
     .rx_clk(gt1_rxusrclk2_i), .rx_rst(gt1_rx_system_reset_c),
     .ev_good(qwn1_byv & ~qwn1_ce), .ev_err(qwn1_byv & qwn1_ce),
     .ev_fid(qwn1_fidp), .ev_hv(qwn1_hv), .ev_hd(qwn1_hd),
     .dst_i(qwn1_dst), .pd_i(qwn1_pd),
     .tx_clk(gt1_txusrclk2_i), .rxhb_clk(gt1_rxusrclk2_i),
     .qpll_i(qwn_qplllock),
     .drpclk(drpclk_in_i),
     .good_cnt(dbg1_good_cnt), .err_cnt(dbg1_err_cnt),
     .fid_cnt(dbg1_fid_cnt), .hv_cnt(dbg1_hv_cnt), .hd_cnt(dbg1_hd_cnt),
     .dst_l(dbg1_dst_l), .pd_l(dbg1_pd_l),
     .qpll_l(dbg1_qpll), .tx_hb(dbg1_tx_hb), .rx_hb(dbg1_rx_hb));

   // VIO : control (probe_out) + status (probe_in), clocked by free-running drpclk
   //
   // *** OPERATIONAL INVARIANT -- NEVER TOUCH probe_out0 (vio_soft_reset). ***
   // SR=0 at all times during measurement campaigns. A soft reset restarts
   // the GT init FSMs AND re-rolls every free-running phase in the system
   // (TX/MMCM inter-lane offsets, divider phase) -> every calibration and
   // every "constant offset cancels in post-processing" assumption dies.
   // Autonomous bring-up is already handled by gt_reset_on_los; manual
   // probe_out0 exists for bench recovery ONLY, never inside a run.
   //
   // probe_out2 (vio_cdrhold_mode) is the campaign's A/B dose-response lever
   // -- semantics + measured results at its wire declaration above. Driven
   // by work/vio_cdr_mode.tcl.
   vio_0 u_qwn_vio (
     .clk        (drpclk_in_i),
     .probe_out0 (vio_soft_reset),     // 1b  *** NEVER touch (see above) ***
     .probe_out1 (qwn_loopback_sel),   // 3b  000=norm 010=NE-PCS 001=NE-PMA
     .probe_out2 (vio_cdrhold_mode),   // 2b
     .probe_out3 (vio_txinh_mode),     // 2b
     .probe_out4 (vio_txdis_mode),     // 2b  SFP laser: 0=fab 1=OFF 2=ON
     .probe_out5 (vio_stat_clr),       // 1b  clear SFP fault/LOS sticky (both lanes)
     .probe_out6 (vio1_txdis_mode),    // 2b  lane-1 SFP laser: 0=fab 1=OFF 2=ON
     .probe_in0  (gt0_rxfsmresetdone_i),
     .probe_in1  (gt0_txfsmresetdone_i),
     .probe_in2  (qwn_lock),
     .probe_in3  (dbg_good_cnt),
     .probe_in4  (dbg_err_cnt),
     .probe_in5  (dbg_fid_cnt),
     .probe_in6  (dbg_hv_cnt),
     .probe_in7  (dbg_hd_cnt),
     .probe_in8  (dbg_dst_l),
     .probe_in9  (dbg_pd_l),
     .probe_in10 (qwn_rxcdrhold_eff),
     .probe_in11 (qwn_gate),
     .probe_in12 (dbg_qpll),           // QPLL lock (refclk/PLL health)
     .probe_in13 (dbg_tx_hb),          // 16b TX usrclk heartbeat (frozen=no clk)
     .probe_in14 (dbg_rx_hb),          // 16b RX usrclk heartbeat (frozen=no clk)
     .probe_in15 (sfp_stat),           // 8b lane-0 {-,-,-,modabs,los_stk,los,flt_stk,flt}
     .probe_in16 (qwn1_lock),          // lane-1 comma lock
     .probe_in17 (qwn_phase_hist),     // sub-UI phase HISTOGRAM + live ui pack
                                       // {idx[31:28],ui0[27:25],ui1[24:22],
                                       //  cnt[21:0]} -- idx map above. (Was
                                       // dbg1_good_cnt before repurposing.)
     .probe_in18 (dbg1_err_cnt),       // 32b lane-1 code errors
     .probe_in19 (dbg1_hv_cnt),        // 16b lane-1 header-valid count
     .probe_in20 (dbg1_dst_l),         // 8b  lane-1 latched destination
     .probe_in21 (dbg1_pd_l),          // 16b lane-1 latched payload_dur
     .probe_in22 (qwn1_gate),          // lane-1 payload marker (-> H41)
     .probe_in23 (gt1_rxfsmresetdone_i),
     .probe_in24 (sfp1_stat));         // 8b lane-1 {0000,modabs(P2),los_stk,los,0}

   // ILA removed for the TX-fix validation build: its 15-probe capture on the
   // timing-critical rxusrclk2/clkout0 cone dragged the clean +0.287 fabric
   // down to ~-0.005 (the route-marginal CDR->8b10b-decoder path). The VIO
   // (drpclk domain, slack-rich) fully proves the TX fix via dbg_hv_cnt /
   // dbg_dst_l(=0x02) / dbg_pd_l(=0x1234) + qwn_lock + good/err counts.
   // ---- LEAN DIAGNOSTIC ILA: dark->burst analog RE-ACQUIRE capture ----
   // Goal: see EXACTLY what the GTHE2 RX does on light-return after a real
   // ~100us laser-off dark (RXCDRHOLD refuted on HW; cause = analog RX
   // re-acquire). One DEDICATED pipeline-register stage (dont_touch) feeds
   // the ILA so its fanout/placement does NOT load the route-marginal
   // CDR->8b10b cone that broke the old ILA's timing; all probes shift by
   // 1 rxusrclk2 cycle UNIFORMLY -> every inter-signal relationship is
   // preserved for diagnosis. ila_0 reused as-configured (15 probes);
   // build_dbg.tcl already synths ila_0_synth_1 + aggressive timing strat.
   // Trigger on probe8 (il_fidp): captures warmup->FID->8B-header across
   // the dark edge -> il_byte/il_dst/il_pd vs expected, il_lock/il_ce/
   // il_eph show whether comma/phase re-acquire cleanly when light returns.
   (* dont_touch = "true" *) reg [3:0]  il_rc, il_eph;
   (* dont_touch = "true" *) reg [7:0]  il_byte, il_rb, il_dst;
   (* dont_touch = "true" *) reg [15:0] il_pd;
   (* dont_touch = "true" *) reg        il_lock, il_byv, il_ce, il_k,
                                         il_fidp, il_hv, il_hd, il_cdrh, il_rfd;
   always @(posedge gt0_rxusrclk2_i) begin
      il_rc   <= qwn_rc;    il_eph  <= qwn_reph;  il_byte <= qwn_byte;
      il_rb   <= qwn_rb;    il_dst  <= qwn_dst;   il_pd   <= qwn_pd;
      il_lock <= qwn_lock;  il_byv  <= qwn_byv;   il_ce   <= qwn_ce;
      il_k    <= qwn_k;     il_fidp <= qwn_fidp;  il_hv   <= qwn_hv;
      il_hd   <= qwn_hd;    il_cdrh <= qwn_rxcdrhold;
      il_rfd  <= gt0_rxfsmresetdone_i;
   end
   ila_0 u_qwn_ila (
      .clk    (gt0_rxusrclk2_i),
      .probe0 (il_rc),   .probe1 (il_byte), .probe2 (il_eph),
      .probe3 (il_rb),   .probe4 (il_lock), .probe5 (il_byv),
      .probe6 (il_ce),   .probe7 (il_k),    .probe8 (il_fidp),
      .probe9 (il_hv),   .probe10(il_hd),   .probe11(il_dst),
      .probe12(il_pd),   .probe13(il_cdrh), .probe14(il_rfd));
//==========================================================================

endmodule
    
